from _h import *
DAY = 20

N4 = ["1", "2", "3", "4"]
AB = ["a", "b"]

def PICK(id, q, opts, ans, explain, keys=None):
    return mcq(id, q, opts, ans, explain, keys=keys or N4[:len(opts)])

def SH(id, q, can, ex):
    """省略できる？"""
    return dict(choose(id, q, ["省略できる（　）で囲む", "省略できない"], 0 if can else 1, ex), plainKeys=["opts"])

def SUBJ(id, q, opts, ans, ex):
    return dict(choose(id, q, opts, ans, ex), plainKeys=["opts"])

def star(id, q, opts, ans, order, explain):
    return PICK(id, q, opts, ans, ["Answer %d (別冊). Correct order: %s" % (ans + 1, order), explain])

